// Wayland backend: injects input through zcr_ui_controls_v2, the protocol
// Chromium's own Wayland interactive_ui_tests use. Wayland deliberately gives
// clients no way to inject input, so this only works under a compositor that
// offers the global: Chromium's bundled Weston with its ui-controls module
// (third_party/weston/src/tests/ui-controls.c), which script/actions/
// run-tests-wayland.sh starts in CI. The module feeds the events through
// Weston's normal input path (notify_motion() / notify_button() on a seat of
// its own), so focus, wl_surface input regions and stacking all apply, the
// same as for a physical mouse.
//
// Like the X11 backend, libwayland-client is loaded at runtime and the few
// functions used are declared here, so the addon needs no Wayland development
// headers. The protocol's wl_interface is written out by hand below instead
// of being generated by wayland-scanner; it has to match
// third_party/wayland-protocols/unstable/ui-controls/
// ui-controls-unstable-v2.xml.
//
// The addon keeps one connection for the life of the process and serializes
// all use of it with a mutex. It is never closed: ui-controls releases every
// pressed button and puts the pointer back at (0, 0) when its client goes
// away.

#include "impl_linux.h"

#include <dlfcn.h>

#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <mutex>
#include <string>

namespace mouse_input::wayland {

namespace {

// libwayland-client ABI (wayland-util.h / wayland-client-core.h).
struct wl_proxy;
struct wl_display;
struct wl_message {
  const char* name;
  const char* signature;
  const struct wl_interface** types;
};
struct wl_interface {
  const char* name;
  int version;
  int method_count;
  const wl_message* methods;
  int event_count;
  const wl_message* events;
};

constexpr uint32_t kWlDisplayGetRegistry = 1;
constexpr uint32_t kWlRegistryBind = 0;

// zcr_ui_controls_v2 requests and enums.
constexpr uint32_t kSendMouseMove = 1;
constexpr uint32_t kSendMouseButton = 2;
constexpr uint32_t kMouseButtonLeft = 0;
constexpr uint32_t kMouseButtonMiddle = 1;
constexpr uint32_t kMouseButtonRight = 2;
constexpr uint32_t kMouseButtonStateUp = 1;
constexpr uint32_t kMouseButtonStateDown = 2;
constexpr uint32_t kModifierNone = 0;
constexpr const char kUiControlsName[] = "zcr_ui_controls_v2";

struct WaylandClient {
  wl_display* (*DisplayConnect)(const char*) = nullptr;
  int (*DisplayDispatch)(wl_display*) = nullptr;
  int (*DisplayRoundtrip)(wl_display*) = nullptr;
  int (*DisplayFlush)(wl_display*) = nullptr;
  int (*DisplayGetError)(wl_display*) = nullptr;
  wl_proxy* (*ProxyMarshalFlags)(wl_proxy*,
                                 uint32_t,
                                 const wl_interface*,
                                 uint32_t,
                                 uint32_t,
                                 ...) = nullptr;
  int (*ProxyAddListener)(wl_proxy*, void (**)(void), void*) = nullptr;
  uint32_t (*ProxyGetVersion)(wl_proxy*) = nullptr;
  const wl_interface* registry_interface = nullptr;
  const wl_interface* surface_interface = nullptr;

  // zcr_ui_controls_v2, which refers to wl_surface_interface and so can only
  // be filled in once the library is loaded.
  const wl_interface* no_types[4] = {};
  const wl_interface* mouse_move_types[4] = {};
  wl_message requests[3] = {};
  wl_message events[1] = {};
  wl_interface ui_controls_interface = {};

  std::string load_error;
  bool ok() const { return load_error.empty(); }
};

template <typename T>
bool Resolve(void* library, const char* name, T* out, std::string* error) {
  *out = reinterpret_cast<T>(::dlsym(library, name));
  if (!*out && error->empty())
    *error = std::string("dlsym(") + name + ") failed";
  return *out != nullptr;
}

const WaylandClient& GetClient() {
  static const WaylandClient* client = [] {
    auto* c = new WaylandClient();
    void* lib = ::dlopen("libwayland-client.so.0", RTLD_NOW | RTLD_LOCAL);
    if (!lib) {
      const char* reason = ::dlerror();
      c->load_error = reason ? reason : "dlopen failed";
      return c;
    }
    std::string& e = c->load_error;
    Resolve(lib, "wl_display_connect", &c->DisplayConnect, &e);
    Resolve(lib, "wl_display_dispatch", &c->DisplayDispatch, &e);
    Resolve(lib, "wl_display_roundtrip", &c->DisplayRoundtrip, &e);
    Resolve(lib, "wl_display_flush", &c->DisplayFlush, &e);
    Resolve(lib, "wl_display_get_error", &c->DisplayGetError, &e);
    // libwayland 1.20+.
    Resolve(lib, "wl_proxy_marshal_flags", &c->ProxyMarshalFlags, &e);
    Resolve(lib, "wl_proxy_add_listener", &c->ProxyAddListener, &e);
    Resolve(lib, "wl_proxy_get_version", &c->ProxyGetVersion, &e);
    Resolve(lib, "wl_registry_interface", &c->registry_interface, &e);
    Resolve(lib, "wl_surface_interface", &c->surface_interface, &e);
    if (!c->ok())
      return c;

    c->mouse_move_types[2] = c->surface_interface;
    c->requests[0] = {"send_key_events", "uuuu", c->no_types};
    c->requests[1] = {"send_mouse_move", "ii?ou", c->mouse_move_types};
    c->requests[2] = {"send_mouse_button", "uuuu", c->no_types};
    c->events[0] = {"request_processed", "u", c->no_types};
    c->ui_controls_interface = {kUiControlsName, 1, 3,
                                c->requests,     1, c->events};
    return c;
  }();
  return *client;
}

// Error codes reported in InjectResult::error.
constexpr int64_t kErrorNoLibrary = 1;
constexpr int64_t kErrorNoDisplay = 2;
constexpr int64_t kErrorNoUiControls = 3;
constexpr int64_t kErrorProtocol = 4;
constexpr int64_t kErrorUnsupported = 5;

// State of the addon's connection, guarded by Connection's lock.
struct State {
  wl_display* display = nullptr;
  wl_proxy* registry = nullptr;
  wl_proxy* ui_controls = nullptr;
  uint32_t ui_controls_name = 0;
  uint32_t next_id = 0;
  uint32_t last_processed = 0;
  bool broken = false;
  // Where the last processed move put the pointer. Wayland has no way for a
  // client to ask where the pointer is, so this is what GetCursorPos()
  // reports. ui-controls starts the pointer at (0, 0).
  int cursor_x = 0;
  int cursor_y = 0;
};

State& GetState() {
  static State state;
  return state;
}

void HandleGlobal(void* data,
                  wl_proxy* registry,
                  uint32_t name,
                  const char* interface,
                  uint32_t version) {
  auto* state = static_cast<State*>(data);
  if (std::strcmp(interface, kUiControlsName) == 0)
    state->ui_controls_name = name;
}

void HandleGlobalRemove(void* data, wl_proxy* registry, uint32_t name) {}

void HandleRequestProcessed(void* data, wl_proxy* ui_controls, uint32_t id) {
  static_cast<State*>(data)->last_processed = id;
}

// Laid out like the wl_registry_listener / zcr_ui_controls_v2_listener
// structs wayland-scanner would generate.
struct RegistryListener {
  void (*global)(void*, wl_proxy*, uint32_t, const char*, uint32_t);
  void (*global_remove)(void*, wl_proxy*, uint32_t);
};
const RegistryListener kRegistryListener = {HandleGlobal, HandleGlobalRemove};

struct UiControlsListener {
  void (*request_processed)(void*, wl_proxy*, uint32_t);
};
const UiControlsListener kUiControlsListener = {HandleRequestProcessed};

template <typename Listener>
int AddListener(wl_proxy* proxy, const Listener* listener, void* data) {
  return GetClient().ProxyAddListener(
      proxy, reinterpret_cast<void (**)(void)>(const_cast<Listener*>(listener)),
      data);
}

// Holds the addon's connection, opening it and binding zcr_ui_controls_v2 on
// first use, and the lock that serializes access to it.
class Connection {
 public:
  Connection() : lock_(Mutex()) {
    const WaylandClient& c = GetClient();
    if (!c.ok()) {
      error_ = kErrorNoLibrary;
      return;
    }
    State& s = GetState();
    if (s.broken) {
      error_ = kErrorProtocol;
      return;
    }
    if (!s.display) {
      // nullptr uses $WAYLAND_DISPLAY. Retried while it fails.
      s.display = c.DisplayConnect(nullptr);
      if (!s.display) {
        error_ = kErrorNoDisplay;
        return;
      }
      auto* display_proxy = reinterpret_cast<wl_proxy*>(s.display);
      s.registry = c.ProxyMarshalFlags(
          display_proxy, kWlDisplayGetRegistry, c.registry_interface,
          c.ProxyGetVersion(display_proxy), 0, nullptr);
      AddListener(s.registry, &kRegistryListener, &s);
      if (c.DisplayRoundtrip(s.display) < 0) {
        s.broken = true;
        error_ = kErrorProtocol;
        return;
      }
      if (s.ui_controls_name) {
        s.ui_controls = c.ProxyMarshalFlags(
            s.registry, kWlRegistryBind, &c.ui_controls_interface, 1, 0,
            s.ui_controls_name, kUiControlsName, 1u, nullptr);
        AddListener(s.ui_controls, &kUiControlsListener, &s);
      }
    }
    if (!s.ui_controls)
      error_ = kErrorNoUiControls;
  }
  Connection(const Connection&) = delete;
  Connection& operator=(const Connection&) = delete;

  wl_proxy* ui_controls() const {
    return error_ ? nullptr : GetState().ui_controls;
  }
  int64_t error() const { return error_; }

  uint32_t NextId() { return ++GetState().next_id; }

  // Waits until the compositor reports request |id| processed: by then it
  // has sent the resulting events to the client with pointer focus.
  bool WaitProcessed(uint32_t id) {
    const WaylandClient& c = GetClient();
    State& s = GetState();
    while (s.last_processed < id) {
      if (c.DisplayDispatch(s.display) < 0) {
        s.broken = true;
        return false;
      }
    }
    return true;
  }

 private:
  static std::mutex& Mutex() {
    static std::mutex mutex;
    return mutex;
  }

  std::lock_guard<std::mutex> lock_;
  int64_t error_ = 0;
};

InjectResult Fail(int expected, int64_t error) {
  InjectResult result;
  result.expected = expected;
  result.error = error;
  return result;
}

uint32_t ButtonCode(Button button) {
  switch (button) {
    case Button::kLeft:
      return kMouseButtonLeft;
    case Button::kMiddle:
      return kMouseButtonMiddle;
    case Button::kRight:
      return kMouseButtonRight;
  }
  return kMouseButtonLeft;
}

}  // namespace

// (x, y) are global compositor coordinates, which are logical pixels (DIPs).
InjectResult Move(int x, int y) {
  Connection c;
  if (!c.ui_controls())
    return Fail(1, c.error());
  const uint32_t id = c.NextId();
  GetClient().ProxyMarshalFlags(c.ui_controls(), kSendMouseMove, nullptr, 1, 0,
                                x, y, static_cast<wl_proxy*>(nullptr), id);
  if (!c.WaitProcessed(id))
    return Fail(1, kErrorProtocol);
  GetState().cursor_x = x;
  GetState().cursor_y = y;
  InjectResult result;
  result.expected = 1;
  result.sent = 1;
  return result;
}

InjectResult Press(Button button, bool down) {
  Connection c;
  if (!c.ui_controls())
    return Fail(1, c.error());
  const uint32_t id = c.NextId();
  GetClient().ProxyMarshalFlags(
      c.ui_controls(), kSendMouseButton, nullptr, 1, 0, ButtonCode(button),
      down ? kMouseButtonStateDown : kMouseButtonStateUp, kModifierNone, id);
  if (!c.WaitProcessed(id))
    return Fail(1, kErrorProtocol);
  InjectResult result;
  result.expected = 1;
  result.sent = 1;
  return result;
}

// zcr_ui_controls_v2 has no axis request.
InjectResult Wheel(int delta, bool horizontal) {
  return Fail(std::abs(delta) / 120, kErrorUnsupported);
}

bool GetCursorPos(int* x, int* y, int64_t* error) {
  Connection c;
  if (!c.ui_controls()) {
    *error = c.error();
    return false;
  }
  *x = GetState().cursor_x;
  *y = GetState().cursor_y;
  return true;
}

// A client cannot ask a Wayland compositor what is under a point.
bool IsWindowAtPoint(const void* handle,
                     size_t handle_size,
                     int x,
                     int y,
                     bool* supported) {
  *supported = false;
  return false;
}

Diagnostics GetDiagnostics() {
  Diagnostics d;
  d.emplace_back("backend", StringValue("ui-controls"));
  const char* wayland_display = std::getenv("WAYLAND_DISPLAY");
  d.emplace_back("waylandDisplay",
                 StringValue(wayland_display ? wayland_display : ""));
  const char* session_type = std::getenv("XDG_SESSION_TYPE");
  d.emplace_back("sessionType", StringValue(session_type ? session_type : ""));
  const WaylandClient& client = GetClient();
  d.emplace_back("libraryLoaded", BoolValue(client.ok()));
  if (!client.ok()) {
    d.emplace_back("libraryError", StringValue(client.load_error));
    d.emplace_back("available", BoolValue(false));
    return d;
  }
  Connection c;
  d.emplace_back("displayOpened", BoolValue(GetState().display != nullptr));
  d.emplace_back("uiControls", BoolValue(c.ui_controls() != nullptr));
  if (c.error())
    d.emplace_back("error", IntValue(c.error()));
  d.emplace_back("available", BoolValue(c.ui_controls() != nullptr));
  return d;
}

}  // namespace mouse_input::wayland
